// Fail-closed auth. Instantly is told this URL with ?t=<VIO_WEBHOOK_TOKEN>; an open endpoint here
// would let anyone mark a prospect bounced or unsubscribed, i.e. suppress them permanently.
const expected = $env.VIO_WEBHOOK_TOKEN;
const item = $input.item.json;
const q = item.query || {}; const h = item.headers || {};
const got = q.t || q.token || h['x-vio-token'];
if (!expected) throw new Error('REFUSED: VIO_WEBHOOK_TOKEN not set (fail-closed)');
if (!got || String(got) !== String(expected)) throw new Error('REFUSED: bad or missing token');
return { json: item.body || item };

// Turn an Instantly event into the two things the sheet actually needs: an Events row (what
// happened, when) and — only sometimes — a channel_state_email transition.
//
// A SEND IS NOT A STAGE CHANGE. The live sheet's channel_state_email dropdown is an engagement
// ladder: needs_review > pending_approval > approved > enrolled > replied > positive > booked,
// plus terminal rejected/dropped/unsubscribed/bounced. There is no 'sent' in it, and inventing one
// would put an off-vocabulary value into a column staff filter on. Delivery is a FACT with a
// timestamp, so it goes to Events and the stage stays 'enrolled' until the prospect does something.
//
// Replies are deliberately NOT handled here — VIO-inbound-reply-to-call already owns them,
// including the OpenAI sentiment pass. Two workflows writing reply state would race.
const b = $input.first().json || {};
const clean = (v, n = 200) => (typeof v === 'string' ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, n) : '');
const ev = clean(b.event_type || b.event || b.type, 60).toLowerCase();
const email = clean(b.lead_email || b.email || b.contact_email || b.to_email, 160).toLowerCase();
const campaign = clean(b.campaign_id || b.campaign, 80);
const when = clean(b.timestamp || b.event_timestamp, 40) || new Date().toISOString();

if (!/^[^\s@,;<>"]+@[^\s@,;<>"]+\.[^\s@,;<>"]+$/.test(email)) {
  throw new Error(`REFUSED: no usable lead email on this event (${ev || 'unknown type'}) — refusing to guess which row to change.`);
}

// stage: null means "record the event, do not touch the ladder".
let action = null, stage = null, suppress = null;
if (/bounce/.test(ev))            { action = 'bounced';      stage = 'bounced';      suppress = 'bounced'; }
else if (/unsub|opt.?out/.test(ev)){ action = 'unsubscribed'; stage = 'unsubscribed'; suppress = 'opt_out'; }
else if (/sent|delivered/.test(ev)){ action = 'send'; }
else if (/open/.test(ev))          { action = 'open'; }
else if (/click|link/.test(ev))    { action = 'click'; }
else if (/repl/.test(ev))          { action = 'reply_seen'; }   // recorded only; the reply brain owns the stage
else                               { action = `other:${ev || 'unknown'}`; }

return [{ json: { email, campaign, when, event_type: ev, action, stage, suppress } }];

// Fan out into the rows each tab needs. Only what actually happened is written.
const e = $input.first().json;
const out = [{ json: {
  _kind: 'event',
  timestamp: e.when, lead_email: e.email, tool: 'instantly', action: e.action, units: 1,
  est_cost_usd: '',                       // measure, don't estimate — the webhook itself bills nothing
  result: `instantly ${e.event_type || e.action}${e.campaign ? ' on ' + e.campaign : ''}`,
  workflow: 'VIO-instantly-events',
} }];
if (e.stage) {
  out.push({ json: { _kind: 'lead', contact_email: e.email,
                     channel_state_email: e.stage, updated_at: e.when } });
}
if (e.suppress) {
  // A bounce or an opt-out must reach Suppression, or the same person is contacted again on
  // another channel. Append-only, matched later on ANY identifier.
  out.push({ json: { _kind: 'suppress', identifier_type: 'email', identifier_value: e.email,
                     reason: e.suppress, added_at: e.when, added_by: 'VIO-instantly-events' } });
}
return out;
